-- Gridline v2 · migration 008 · Crew plan (was: Project team) and Precon services (was: Preconstruction)
-- work like today's pages:
--  * schedule dates on the project (precon start / end, construction start, substantial completion, closeout);
--    the crew plan's precon, construction and closeout weeks follow them
--  * crew members sit in teams (Operations, Site operations, Corporate resources), have a posting rate,
--    a % quoted, per diem (place, dates, week days / all days, hotel / meals / both) and relocation; pay
--    escalates each year by the project's salary escalation %
--  * the crew's quoted total is the "General conditions" line of the price roll-up
--  * Precon services has its own team, with hours per precon task (default tasks + ad-hoc ones per project)
--  * Precon services and Project overheads: Quoted % (was: allowable markup) — quoted = billable × %
--  * each person picks which crew plan columns they see (this project or all projects)
SET search_path = gridline, public;

-- ---------------------------------------------------------------- people
ALTER TABLE Staff ADD COLUMN IF NOT EXISTS TeamGroup text NOT NULL DEFAULT 'operations';
DO $$ BEGIN
  ALTER TABLE Staff ADD CONSTRAINT StaffTeamGroupCheck CHECK (TeamGroup IN ('operations', 'siteops', 'corporate'));
EXCEPTION WHEN duplicate_object THEN NULL; END $$;
-- superintendents, safety and MEP people work on site; estimators and precon managers are corporate
UPDATE Staff s SET TeamGroup = CASE
    WHEN r.RoleName ILIKE '%superintendent%' OR r.RoleName ILIKE '%safety%' OR r.RoleName ILIKE '%MEP%' THEN 'siteops'
    WHEN r.RoleName ILIKE '%estimator%' OR r.RoleName ILIKE '%pre-construction%' OR r.RoleName ILIKE '%precon%' THEN 'corporate'
    ELSE 'operations' END
FROM StaffRole r WHERE r.StaffRoleId = s.StaffRoleId AND s.TeamGroup = 'operations'
  AND NOT EXISTS (SELECT 1 FROM SchemaChange WHERE ChangeNo = 8);

-- ---------------------------------------------------------------- project schedule dates and pay escalation
ALTER TABLE Project
  ADD COLUMN IF NOT EXISTS SalaryEscalationPct numeric(6,3) NOT NULL DEFAULT 3,   -- pay rises this % each calendar year
  ADD COLUMN IF NOT EXISTS PreconStartOn date,
  ADD COLUMN IF NOT EXISTS PreconEndOn   date,
  ADD COLUMN IF NOT EXISTS BuildStartOn  date,      -- was: Est construction start date
  ADD COLUMN IF NOT EXISTS BuildEndOn    date,      -- was: Construction substantial completion date
  ADD COLUMN IF NOT EXISTS CloseoutOn    date;      -- was: Closeout date
UPDATE Project p SET
  PreconStartOn = (SELECT min(StartsOn) FROM ProjectWeek w WHERE w.ProjectId = p.ProjectId AND w.Phase = 'precon'),
  PreconEndOn   = (SELECT max(StartsOn) + 6 FROM ProjectWeek w WHERE w.ProjectId = p.ProjectId AND w.Phase = 'precon'),
  BuildStartOn  = (SELECT min(StartsOn) FROM ProjectWeek w WHERE w.ProjectId = p.ProjectId AND w.Phase = 'build'),
  BuildEndOn    = (SELECT max(StartsOn) + 6 FROM ProjectWeek w WHERE w.ProjectId = p.ProjectId AND w.Phase = 'build'),
  CloseoutOn    = (SELECT max(StartsOn) + 6 FROM ProjectWeek w WHERE w.ProjectId = p.ProjectId AND w.Phase = 'closeout')
WHERE p.BuildStartOn IS NULL;

-- ---------------------------------------------------------------- per diem rates (was: PerDiemRates, GSA)
CREATE TABLE IF NOT EXISTS PerDiemPlace (
  PlaceId       bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  FiscalYear    smallint NOT NULL,
  City          text NOT NULL,
  County        text,
  StateCode     text,
  LocationDefined text,
  Lodging       int[] NOT NULL CHECK (array_length(Lodging, 1) = 12),   -- hotel per night, Jan … Dec
  Meals         int NOT NULL
);
CREATE INDEX IF NOT EXISTS IxPerDiemPlace ON PerDiemPlace (FiscalYear, StateCode, City);
CREATE TABLE IF NOT EXISTS PerDiemZip (             -- zip → place (optional; loaded later from the GSA file)
  Zip           text NOT NULL,
  FiscalYear    smallint NOT NULL,
  PlaceId       bigint NOT NULL REFERENCES PerDiemPlace ON DELETE CASCADE,
  PRIMARY KEY (Zip, FiscalYear)
);

-- ---------------------------------------------------------------- crew plan members
ALTER TABLE TeamMember
  ADD COLUMN IF NOT EXISTS TeamGroup     text NOT NULL DEFAULT 'operations',
  ADD COLUMN IF NOT EXISTS QuotedPct     numeric(7,3) NOT NULL DEFAULT 100,      -- was: % Quoted (RateDiscountPC)
  ADD COLUMN IF NOT EXISTS PerDiemPlaceId bigint REFERENCES PerDiemPlace ON DELETE SET NULL,
  ADD COLUMN IF NOT EXISTS PerDiemStart  date,
  ADD COLUMN IF NOT EXISTS PerDiemEnd    date,
  ADD COLUMN IF NOT EXISTS PerDiemDays   text NOT NULL DEFAULT 'weekdays',        -- weekdays | alldays
  ADD COLUMN IF NOT EXISTS PerDiemKind   text NOT NULL DEFAULT 'both',            -- hotel | meals | both
  ADD COLUMN IF NOT EXISTS PerDiemDaysCount int NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS PerDiemCost   numeric(14,2) NOT NULL DEFAULT 0;
DO $$ BEGIN
  ALTER TABLE TeamMember ADD CONSTRAINT TeamMemberGroupCheck CHECK (TeamGroup IN ('operations', 'siteops', 'corporate'));
EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN
  ALTER TABLE TeamMember ADD CONSTRAINT TeamMemberPerDiemCheck CHECK (PerDiemDays IN ('weekdays', 'alldays') AND PerDiemKind IN ('hotel', 'meals', 'both'));
EXCEPTION WHEN duplicate_object THEN NULL; END $$;
-- existing members (first run only): team from their person, % quoted from the old bill rate, old travel becomes per diem
UPDATE TeamMember m SET TeamGroup = s.TeamGroup FROM Staff s WHERE s.StaffId = m.StaffId AND NOT EXISTS (SELECT 1 FROM SchemaChange WHERE ChangeNo = 8);
UPDATE TeamMember SET QuotedPct = round(BillRate / HourlyCost * 100, 3)
WHERE HourlyCost > 0 AND BillRate > 0 AND QuotedPct = 100 AND NOT EXISTS (SELECT 1 FROM SchemaChange WHERE ChangeNo = 8);
UPDATE TeamMember m SET PerDiemCost = (tr.LodgingDaily + tr.MealsDaily) * m.TravelDays, PerDiemDaysCount = m.TravelDays
FROM TravelRate tr WHERE tr.TravelRateId = m.TravelRateId AND m.PerDiemCost = 0 AND m.TravelDays > 0;

-- which crew plan columns a person sees (ProjectId 0 = every project)
CREATE TABLE IF NOT EXISTS ColumnChoice (
  UserId        bigint NOT NULL REFERENCES AppUser ON DELETE CASCADE,
  GridKey       text NOT NULL,
  ProjectId     bigint NOT NULL DEFAULT 0,
  Columns       text[] NOT NULL,
  PRIMARY KEY (UserId, GridKey, ProjectId)
);

-- ---------------------------------------------------------------- precon tasks (was: Tasks / ProjectTasks)
ALTER TABLE Activity
  ADD COLUMN IF NOT EXISTS IsDefault boolean NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS ProjectId bigint REFERENCES Project ON DELETE CASCADE,   -- set = ad-hoc task of that project
  ADD COLUMN IF NOT EXISTS IsActive  boolean NOT NULL DEFAULT true;
UPDATE Activity SET IsActive = false WHERE Phase = 'precon' AND ProjectId IS NULL
  AND ActivityName IN ('Kick-off and estimate plan', 'Scope packages', 'Bid leveling meetings');
INSERT INTO Activity (Phase, ActivityName, SortOrder, IsDefault)
SELECT 'precon', x.n, x.o, x.d FROM (VALUES
  ('Design phase schedule creation', 1, true), ('Estimate - conceptual', 2, true), ('Savings ideas session', 3, false),
  ('Cost model', 4, false), ('Constructability review', 5, false), ('Estimate - schematic', 6, true),
  ('Estimate - design development 50%', 7, true), ('Estimate - design development 100%', 8, true), ('Estimate - construction docs 50%', 9, true),
  ('GMP - prequal / generate interest', 10, false), ('GMP - write scopes / front ends', 11, true), ('GMP - distribute packages / supplements', 12, false),
  ('GMP - scope review meetings', 13, false), ('GMP - final compilation / review', 14, true), ('Client meetings', 15, true), ('Other', 16, true)) x(n, o, d)
WHERE NOT EXISTS (SELECT 1 FROM Activity a WHERE a.Phase = 'precon' AND a.ActivityName = x.n AND a.ProjectId IS NULL);

CREATE TABLE IF NOT EXISTS VersionTask (            -- the task columns on a version's Precon services page
  VersionId     bigint NOT NULL REFERENCES ProjectVersion ON DELETE CASCADE,
  ActivityId    int NOT NULL REFERENCES Activity ON DELETE CASCADE,
  SortOrder     smallint NOT NULL,
  PRIMARY KEY (VersionId, ActivityId)
);
CREATE TABLE IF NOT EXISTS PreconMember (           -- precon team (was: Precon resource grid)
  PreconMemberId bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  VersionId     bigint NOT NULL REFERENCES ProjectVersion ON DELETE CASCADE,
  StaffId       bigint REFERENCES Staff,
  StaffRoleId   int REFERENCES StaffRole,
  RoleLabel     text NOT NULL,
  TeamGroup     text NOT NULL DEFAULT 'corporate' CHECK (TeamGroup IN ('operations', 'siteops', 'corporate')),
  SortKey       numeric(12,4) NOT NULL,
  PostingRate   numeric(10,2) NOT NULL DEFAULT 0,      -- actual cost per hour
  QuotedRate    numeric(10,2),                         -- the role's standard rate (shown for reference)
  RowRev        int NOT NULL DEFAULT 1
);
CREATE INDEX IF NOT EXISTS IxPreconMemberVersion ON PreconMember (VersionId, SortKey);
CREATE TABLE IF NOT EXISTS PreconMemberTask (
  PreconMemberId bigint NOT NULL REFERENCES PreconMember ON DELETE CASCADE,
  ActivityId    int NOT NULL REFERENCES Activity ON DELETE CASCADE,
  Hours         numeric(8,2) NOT NULL DEFAULT 0 CHECK (Hours >= 0),
  PRIMARY KEY (PreconMemberId, ActivityId)
);

-- every version starts with the default tasks
INSERT INTO VersionTask (VersionId, ActivityId, SortOrder)
SELECT v.VersionId, a.ActivityId, a.SortOrder FROM ProjectVersion v CROSS JOIN Activity a
WHERE a.Phase = 'precon' AND a.IsDefault AND a.ProjectId IS NULL AND a.IsActive
  AND NOT EXISTS (SELECT 1 FROM SchemaChange WHERE ChangeNo = 8)
ON CONFLICT DO NOTHING;
-- crew members with precon-week hours become the precon team; their hours go on "Other"
INSERT INTO PreconMember (VersionId, StaffId, StaffRoleId, RoleLabel, TeamGroup, SortKey, PostingRate, QuotedRate)
SELECT v.VersionId, m.StaffId, m.StaffRoleId, m.RoleLabel, m.TeamGroup, m.SortKey, coalesce(m.HourlyCost, 0), m.BillRate
FROM TeamMember m JOIN ProjectVersion v ON v.ProjectId = m.ProjectId
WHERE EXISTS (SELECT 1 FROM TeamMemberWeek mw JOIN ProjectWeek wk ON wk.WeekId = mw.WeekId AND wk.Phase = 'precon' WHERE mw.TeamMemberId = m.TeamMemberId AND mw.Hours > 0)
  AND NOT EXISTS (SELECT 1 FROM PreconMember p WHERE p.VersionId = v.VersionId)
  AND NOT EXISTS (SELECT 1 FROM SchemaChange WHERE ChangeNo = 8);
INSERT INTO PreconMemberTask (PreconMemberId, ActivityId, Hours)
SELECT p.PreconMemberId, (SELECT ActivityId FROM Activity WHERE Phase = 'precon' AND ActivityName = 'Other' AND ProjectId IS NULL LIMIT 1), sum(mw.Hours)
FROM PreconMember p JOIN ProjectVersion v ON v.VersionId = p.VersionId
JOIN TeamMember m ON m.ProjectId = v.ProjectId AND m.SortKey = p.SortKey AND m.RoleLabel = p.RoleLabel
JOIN TeamMemberWeek mw ON mw.TeamMemberId = m.TeamMemberId JOIN ProjectWeek wk ON wk.WeekId = mw.WeekId AND wk.Phase = 'precon'
WHERE NOT EXISTS (SELECT 1 FROM PreconMemberTask t WHERE t.PreconMemberId = p.PreconMemberId)
  AND NOT EXISTS (SELECT 1 FROM SchemaChange WHERE ChangeNo = 8)
GROUP BY p.PreconMemberId HAVING sum(mw.Hours) > 0;

-- ---------------------------------------------------------------- Quoted % on precon services and project overheads
ALTER TABLE ProjectVersion
  ADD COLUMN IF NOT EXISTS PreconQuotedPct numeric(7,3) NOT NULL DEFAULT 100,   -- was: PreconDeptAllowableMarkup
  ADD COLUMN IF NOT EXISTS GenreqQuotedPct numeric(7,3) NOT NULL DEFAULT 100,   -- was: GeneralRequirementsAllowableMarkup
  ADD COLUMN IF NOT EXISTS ReserveGenconds text[] NOT NULL DEFAULT '{}';        -- reserves whose base also takes general conditions
ALTER TABLE CostLine ADD COLUMN IF NOT EXISTS CsiCode text;
-- quoted rate follows the Quoted %: billable lines rate × %, others 0 (first run only)
UPDATE CostLine SET QuotedRate = CASE WHEN IsBillable THEN Rate ELSE 0 END
WHERE NOT EXISTS (SELECT 1 FROM SchemaChange WHERE ChangeNo = 8);

-- ---------------------------------------------------------------- General conditions (= the crew plan's quoted total)
INSERT INTO MarkupType (MarkupCode, MarkupName, SortOrder, AppliesTo, DefaultRatePct)
VALUES ('genconds', 'General conditions', 25, 'direct', 0) ON CONFLICT (MarkupCode) DO NOTHING;
ALTER TABLE ProjectVersion DROP CONSTRAINT IF EXISTS VersionFeeExcludesCheck;
ALTER TABLE ProjectVersion ADD CONSTRAINT VersionFeeExcludesCheck CHECK (FeeExcludes <@ ARRAY['genreq', 'precon', 'genconds', 'reserves', 'bond', 'cover']::text[]);

